SELECT i.inv_date_sk, i.inv_item_sk, it.i_item_id, i.inv_quantity_on_hand, i.inv_quantity_on_hand * it.i_current_price AS inventory_value, CASE WHEN i.inv_quantity_on_hand > 745 THEN 'High' ELSE 'Low' END AS stock_level, CASE WHEN it.i_current_price > 9.93 THEN 'Expensive' ELSE 'Affordable' END AS price_category, it.i_product_name, it.i_brand, it.i_category FROM inventory i JOIN item it ON i.inv_item_sk = it.i_item_sk WHERE i.inv_quantity_on_hand > 801 AND it.i_current_price < 4.46
